#!/usr/bin/perl

# Generate the custom-convert.conf file shipped with the FFmpeg plugin.
#
# This program is free software; you can redistribute it and/or
# modify it under the terms of the GNU General Public License,
# version 2.
#
# Usage:
#   perl tools/gen-convert-conf.pl                > custom-convert.conf
#   perl tools/gen-convert-conf.pl --output=FILE
#
# The generated file is loaded by Slim::Player::TranscodingHelper.  Every
# conversion is described twice: once with a local file ($FILE$, capability
# "F") and once with a remote URL ($URL$, capability "R").  The plugin's
# Plugins::FFmpeg::Conversion module re-orders/renumbers the resulting
# profile instances at runtime, depending on the "mode" preference.

use strict;
use warnings;

use Getopt::Long qw(GetOptions);

# Audio content types LMS knows about.  These mirror the source format names
# used in LMS' own convert.conf plus the conversion-only types used by the
# PlayVideo plugin (ac3/eac3/dts/truehd).
my @SOURCES = qw(
	aac alc alcx ape aif flc mp3 mp4 mp4x mpc ogg ogf ops pcm sls wav
	wma wmal wmap wvp wvpx ac3 eac3 dts truehd
);

# DSD (and DSD in WavPack) sources.  These profiles are only enabled when the
# "enableDSD" preference is on (experimental); they are emitted here and
# removed at runtime by Plugins::FFmpeg::Conversion when DSD is disabled.
my @DSD_SOURCES = qw( dff dsf wvpx );

# Output formats we can produce.  Lossless FLAC, MP3, raw PCM and AIFF.
my @OUTPUTS = qw( flc mp3 pcm aif );

# For DSD sources only FLAC output is offered; DSD is resampled to 176400Hz
# (or to the player's limit via the D capability).
my @DSD_OUTPUTS = qw( flc );

# ffmpeg output arguments per output format.
my %CODEC_ARGS = (
	flc => '-c:a flac -f flac',
	mp3 => '-c:a libmp3lame -q:a $QUALITY$ $BITRATE$ -f mp3',
	pcm => '-c:a pcm_s16le -f s16le',
	aif => '-c:a pcm_s16be -f aiff',
);

# Common ffmpeg arguments.  -nostdin makes sure ffmpeg does not consume the
# server's stdin, -vn/-sn/-dn drops video/subtitle/data streams and
# "-map 0:a:0" selects the first audio stream (cover art lives in a video
# stream in MP3/FLAC/MP4 files).
my $COMMON = '[ffmpeg] -hide_banner -loglevel error -nostdin $START$ %INPUT% $END$ -vn -sn -dn -map 0:a:0 %DSD$RESAMPLE$ -ac $OCHANNELS$';

sub capabilities {
	my ($mode, $output) = @_;

	my $caps = $mode;
	$caps .= 'B:{BITRATE=-b:a %Bk}' if $output eq 'mp3';
	$caps .= 'T:{START=-ss %s}U:{END=-t %w}D:{RESAMPLE=-ar %d}';

	return $caps;
}

sub command {
	my ($mode, $source, $output, $dsd) = @_;

	my $input;
	if ($source eq 'pcm') {
		# Raw PCM has no container/header, so we have to tell ffmpeg the
		# input format, sample rate and channel count.
		$input = '-f s16le -ar $SAMPLERATE$ -ac $CHANNELS$ -i '
			. ($mode eq 'F' ? '$FILE$' : '$URL$');
	}
	else {
		$input = '-i ' . ($mode eq 'F' ? '$FILE$' : '$URL$');
	}

	my $command = $COMMON;
	$command =~ s/%INPUT%/$input/;
	$command =~ s/%DSD/$dsd ? '-ar 176400 ' : ''/e;
	$command .= ' ' . $CODEC_ARGS{$output} . ' -';

	return $command;
}

sub render {
	my $out = '';

	$out .= "# FFmpeg audio decoder conversion profiles for Lyrion Music Server\n";
	$out .= "#\n";
	$out .= "# Generated by tools/gen-convert-conf.pl - do not edit this file by hand.\n";
	$out .= "# Re-generate it with: make custom-convert.conf (or perl tools/gen-convert-conf.pl)\n";
	$out .= "#\n";
	$out .= "# Every block is a local file (F) and a remote URL (R) variant.  The\n";
	$out .= "# profile instance order is adjusted at runtime by\n";
	$out .= "# Plugins::FFmpeg::Conversion according to the plugin.ffmpeg mode\n";
	$out .= "# preference (fallback: ffmpeg last, prefer: ffmpeg first).\n";
	$out .= '# ' . '=' x 76 . "\n\n";

	for my $output (@OUTPUTS) {

		$out .= "# $output output\n\n";

		for my $source (@SOURCES) {

			next if $source eq $output;    # identity conversion, nothing to do
			next if $source eq 'wvpx' && $output eq 'flc';    # DSD block below

			$out .= _block($source, $output, 0);
		}
	}

	$out .= '#' . '=' x 76 . "\n\n";
	$out .= "# DSD sources (experimental, only active when plugin.ffmpeg enableDSD=1)\n";
	$out .= "#\n";
	$out .= "# DSD is decoded at the DSD rate and resampled to 176400Hz.  If the\n";
	$out .= "# player cannot handle 176400Hz, the D capability lowers the rate.\n";
	$out .= "# Plugins::FFmpeg::Conversion removes these profiles when DSD is off.\n\n";

	for my $output (@DSD_OUTPUTS) {

		$out .= "# $output output\n\n";

		for my $source (@DSD_SOURCES) {
			$out .= _block($source, $output, 1);
		}
	}

	return $out;
}

sub _block {
	my ($source, $output, $dsd) = @_;

	my $block = '';

	for my $mode (qw( F R )) {

		my $caps    = capabilities($mode, $output);
		my $command = command($mode, $source, $output, $dsd);

		$block .= "$source $output * *\n";
		$block .= "\t# $caps\n";
		$block .= "\t$command\n\n";
	}

	return $block;
}

sub main {
	my %opt = (output => undef);

	GetOptions(\%opt, 'output=s', 'help|h')
		or die "Usage: $0 [--output=FILE]\n";

	if ($opt{help}) {
		print "Usage: $0 [--output=FILE]\n\n";
		print "Writes the generated custom-convert.conf to STDOUT or FILE.\n";
		return 0;
	}

	my $content = render();

	if (defined $opt{output} && $opt{output} ne '-') {
		open(my $fh, '>', $opt{output}) or die "Cannot open $opt{output}: $!\n";
		print {$fh} $content;
		close($fh) or die "Cannot write $opt{output}: $!\n";
	}
	else {
		print $content;
	}

	return 0;
}

exit(main());
